import { useEffect, useState } from 'react';
import OwnVoice from './pages/OwnVoice.jsx';
import Home from './pages/Home.jsx';
import VoiceCall from './pages/VoiceCall.jsx';
import ClinicList from './pages/ClinicList.jsx';
import LiveHandoff from './pages/LiveHandoff.jsx';
import PhoneCall from './pages/PhoneCall.jsx';
import Plan from './pages/Plan.jsx';
import { strings, detectLang, saveLang } from './i18n.js';
import { primeSpeech } from './agents/speech.js';
import { buildSummary } from './utils/summary.js';
import { stepState } from './utils/steps.js';
import StepRail from './components/StepRail.jsx';
import { IS_LIVE_PHONE } from './agents/index.js';
import { PHONE_AGENT_URL } from './config.js';

const GRADIUM_KEY = 'pawse.gradium';
function loadGradiumChoice() {
  try {
    return localStorage.getItem(GRADIUM_KEY) !== '0'; // on by default, the owner can turn it off
  } catch {
    return true;
  }
}

// home → voice call with Pawse → advice
//   → "call the vet": clinic list → Pawse calls the chosen clinic
//   → "call the insurer": Pawse calls the insurer
//   → plan (summary)
export default function App() {
  const [view, setView] = useState('home'); // home | voice | clinics | phone | plan
  const [lang, setLangState] = useState(detectLang);
  const [triage, setTriage] = useState(null);
  const [vet, setVet] = useState(null);
  const [insurance, setInsurance] = useState(null);
  const [clinic, setClinic] = useState(null);
  const [target, setTarget] = useState(null);
  const [rehearsal, setRehearsal] = useState(false);
  const [gradiumOn, setGradiumOnState] = useState(loadGradiumChoice);
  const [voiceStatus, setVoiceStatus] = useState(null);

  const setGradiumOn = (on) => {
    setGradiumOnState(on);
    try {
      localStorage.setItem(GRADIUM_KEY, on ? '1' : '0');
    } catch {
      /* storage unavailable */
    }
  };

  // Live phone calls only: is Gradium configured, and does this session have its own German voice?
  useEffect(() => {
    if (!IS_LIVE_PHONE) return undefined;
    let alive = true;
    fetch(`${PHONE_AGENT_URL || ''}/api/v1/voice/status`)
      .then((r) => (r.ok ? r.json() : null))
      .then((s) => alive && s && setVoiceStatus(s))
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, []);
  // Unknown status: still offer Gradium; the call falls back to the browser voice on 503.
  const gradiumAvailable = IS_LIVE_PHONE && (!voiceStatus || voiceStatus.gradium_configured === true);
  const ownVoice = !!(voiceStatus && voiceStatus.my_voice_ready);

  const t = strings[lang] || strings.en;
  const Handoff = IS_LIVE_PHONE && !rehearsal ? LiveHandoff : PhoneCall;

  const setLang = (l) => {
    setLangState(l);
    saveLang(l);
  };

  useEffect(() => {
    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : lang;
  }, [lang]);

  const startCall = () => {
    primeSpeech(); // unlock speech on iOS while we are inside the tap
    setTriage(null);
    setVet(null);
    setInsurance(null);
    setClinic(null);
    setView('voice');
  };

  const call = (to) => {
    setRehearsal(false);
    primeSpeech();
    if (to === 'vet') {
      setView('clinics');
      return;
    }
    setTarget(to);
    setView('phone');
  };

  const pickClinic = (c) => {
    setRehearsal(false);
    primeSpeech();
    setClinic(c);
    setTarget('vet');
    setView('phone');
  };

  const callDone = (result) => {
    if (result && target === 'vet') setVet(result);
    if (result && target === 'insurance') setInsurance(result);
    setView(triage ? 'plan' : 'home');
  };

  // One progress rail through the story; shown once there is something to show progress on.
  const rail = <StepRail t={t} steps={stepState({ view, target, triage, vet, insurance })} />;

  if (view === 'ownvoice') return <OwnVoice onBack={() => setView('home')} />;
  if (view === 'voice') {
    return (
      <VoiceCall
        t={t}
        lang={lang}
        triage={triage}
        vet={vet}
        insurance={insurance}
        onTriage={setTriage}
        rail={triage ? rail : null}
        onCall={call}
        onEnd={() => setView(triage ? 'plan' : 'home')}
      />
    );
  }
  if (view === 'clinics') {
    // Going back from the list never restarts the voice call: show the plan instead.
    return <ClinicList t={t} lang={lang} triage={triage} rail={rail} onPick={pickClinic} onBack={() => setView(triage ? 'plan' : 'home')} />;
  }
  if (view === 'phone') {
    return (
      <Handoff
        key={`${target}-${clinic ? clinic.id : ''}`}
        t={t}
        lang={lang}
        rail={rail}
        target={target}
        clinic={target === 'vet' ? clinic : null}
        gradium={gradiumAvailable ? { on: gradiumOn, ownVoice, set: setGradiumOn } : null}
        context={{
          gradiumConsent: gradiumAvailable && gradiumOn,
          voice: ownVoice ? 'my_voice' : 'standard',
          summary: buildSummary({ lang, triage, vet, insurance }),
          clinic: target === 'vet' ? clinic : undefined,
          estimate: vet ? vet.estimate : undefined,
          homeVisitFee: vet ? vet.homeVisitFee : undefined,
        }}
        onDone={callDone}
        onRehearse={() => { setGradiumOn(false); setRehearsal(true); }}
      />
    );
  }
  if (view === 'plan' && triage) {
    return (
      <Plan
        t={t}
        lang={lang}
        triage={triage}
        vet={vet}
        insurance={insurance}
        rail={rail}
        onCall={call}
        onRestart={() => setView('home')}
      />
    );
  }
  return <Home t={t} lang={lang} setLang={setLang} onStart={startCall} onOwnVoice={() => setView('ownvoice')} />;
}
// The interfaces between this frontend and the teammates' agents.
// Keep this file the single source of truth; README.md mirrors it.

/**
 * ============================================================ 1. VOICE AGENT
 * Voice conversation between the user and Pawse. Camera and photos are optional extras.
 * Teammate replaces src/agents/liveVoiceAgent.js.
 *
 * createVoiceAgent({ lang }) returns:
 *   on(cb) -> unsubscribe
 *   start()
 *   end()                          must emit {type:'ended'} exactly once
 *   sendText(text)                 typed text, or a tapped keyword chip
 *   sendImage(file)                a photo the user took or picked (File / Blob)
 *   attachMedia({ audio, video })  MediaStreams from the page; either may be null
 *                                  (audio = mic when wantsAudio; video = only while the camera is on)
 *   setMicMuted(bool)
 *   wantsAudio: boolean            if true the page opens the microphone
 *
 * Events:
 *   {type:'transcript', role:'user'|'ai', text, simulated?, partial?}   live captions;
 *                                                  partial:true = the owner's words still streaming in
 *   {type:'transcribing', on:boolean}              a recorded turn is being turned into text
 *   {type:'speaking', who:'user'|'ai'|'none'}                  drives the avatar
 *   {type:'listening', on:boolean}
 *   {type:'suggestions', items:string[]}                       keyword chips ([] hides them)
 *   {type:'image_received'}                                    the last photo arrived
 *   {type:'triage', level, headline, steps:string[], askVet?:string[], escalation?:string, summary:string}
 *                                                  steps = what the owner does now; askVet = questions for the vet
 *   {type:'error', message}
 *   {type:'ended'}
 *
 * ============================================================ 2. CLINIC SEARCH
 * Finds nearby vet clinics, shown as a list before Pawse calls one.
 * Teammate replaces src/agents/liveClinicSearch.js.
 *
 * searchClinics({ lang, location, triage }) -> Promise<{ clinics: Clinic[] }>
 *   location = { lat, lng } or null (user refused / unavailable)
 *
 * Clinic = { id, name, address, distanceKm, openNow:boolean, hoursText?, emergency?:boolean,
 *            rating?:number, mapsUrl? }
 *
 * ============================================================ 3. PHONE AGENT
 * Pawse calls the chosen clinic or the insurer for the user.
 * Teammate replaces src/agents/livePhoneAgent.js.
 *
 * createPhoneCall({ target:'vet'|'insurance', lang, context }) returns:
 *   on(cb) -> unsubscribe
 *   start()
 *   hangup()
 *   setGradiumConsent?(on:boolean)   optional: change Gradium consent for the remaining lines
 *   answer?(questionId, optionId)    optional: the owner's answer to a {type:'question'} event
 *   setListening?(on:boolean)        optional: play the German call audio (default: background, silent)
 *   context = { summary: string, clinic?: Clinic, estimate?: number, homeVisitFee?: number,
 *               gradiumConsent?: boolean, voice?: 'standard'|'my_voice' }
 *   gradiumConsent === true lets the live agent speak every AI line with Gradium (one voice per call).
 *
 * Events:
 *   {type:'status', state:'dialing'|'connected'|'ended'}
 *   {type:'speaking', who:'ai'|'callee'|'none'}
 *   {type:'line', who:'ai'|'callee', original:string, text:string, simulated?:true}
 *       original language + translation; a callee line that was not really heard is simulated:true
 *   {type:'progress', text}                         plain-language step in the owner's language
 *   {type:'question', id, text, options:[{id, label}]}   the call waits until answer() is called
 *   {type:'answered', id, optionId}
 *   {type:'result', ...}
 *   {type:'error', message}
 *
 * The owner never has to read German: the page shows progress, questions and the result in their
 * language; the German lines are only an optional transcript.
 *
 * Every result carries simulated:boolean. There is no telephony yet, so it is true for now:
 * the page labels it "simulated" and never says "booked".
 * result for 'vet':       {kind:'appointment', time, place, estimate:number, currency, note?,
 *                          homeVisitFee?:number (part of estimate, not reimbursed)}
 * result for 'insurance': {kind:'coverage', covered, currency, deductible, rate, estimate,
 *                          reimbursed, outOfPocket, points:[{ok, text, ref?}]}
 */

export const LEVELS = ['red', 'yellow', 'green'];

/** Problems with a triage event (empty list = OK). */
export function validateTriage(e) {
  const p = [];
  if (!e || typeof e !== 'object') return ['triage is not an object'];
  if (!LEVELS.includes(e.level)) p.push(`level must be one of ${LEVELS.join('|')}`);
  if (!e.headline) p.push('headline missing');
  if (!Array.isArray(e.steps) || !e.steps.length) p.push('steps must be a non-empty array');
  if (e.askVet !== undefined && !(Array.isArray(e.askVet) && e.askVet.every(s => typeof s === 'string'))) p.push('askVet must be an array of strings');
  if (typeof e.summary !== 'string' || !e.summary) p.push('summary missing');
  return p;
}

/** Problems with a clinic list (empty list = OK). */
export function validateClinics(res) {
  const p = [];
  if (!res || !Array.isArray(res.clinics)) return ['expected { clinics: [...] }'];
  res.clinics.forEach((c, i) => {
    if (!c.id) p.push(`clinics[${i}].id missing`);
    if (!c.name) p.push(`clinics[${i}].name missing`);
    if (typeof c.distanceKm !== 'number') p.push(`clinics[${i}].distanceKm must be a number`);
    if (typeof c.openNow !== 'boolean') p.push(`clinics[${i}].openNow must be true/false`);
  });
  return p;
}

/** Problems with a phone-call result (empty list = OK). */
export function validateResult(target, r) {
  const p = [];
  if (!r || typeof r !== 'object') return ['result is not an object'];
  if (typeof r.simulated !== 'boolean') p.push('simulated must be true/false (true unless a real call happened)');
  if (target === 'vet') {
    if (r.kind !== 'appointment') p.push("vet result kind must be 'appointment'");
    if (!r.time) p.push('time missing');
    if (typeof r.estimate !== 'number') p.push('estimate must be a number');
  } else if (target === 'insurance') {
    if (r.kind !== 'coverage') p.push("insurance result kind must be 'coverage'");
    for (const k of ['deductible', 'rate', 'estimate', 'reimbursed', 'outOfPocket']) {
      if (typeof r[k] !== 'number') p.push(`${k} must be a number`);
    }
    if (!Array.isArray(r.points)) p.push('points must be an array');
  } else p.push(`unknown target ${target}`);
  return p;
}
// Central switches. Set them in .env.local (see .env.example).
// import.meta.env is undefined outside Vite (e.g. plain-Node checks), so guard it.
const env = (typeof import.meta !== 'undefined' && import.meta.env) || {};

const param = (k) => {
  try {
    return new URLSearchParams(window.location.search).get(k);
  } catch {
    return null;
  }
};

/** 'mock' = scripted demo (default). 'live' = the Pawse backend. "?live=1" in the URL switches all three at runtime. */
const DEMO_ALL = param('demo') === '1';
const LIVE_ALL = !DEMO_ALL && param('live') === '1';
export const VOICE_AGENT = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_VOICE_AGENT || 'mock';
export const CLINIC_SEARCH = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_CLINIC_SEARCH || 'mock';
export const PHONE_AGENT = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_PHONE_AGENT || 'mock';

export const VOICE_AGENT_URL = env.VITE_VOICE_AGENT_URL || '';
export const CLINIC_SEARCH_URL = env.VITE_CLINIC_SEARCH_URL || '';
export const PHONE_AGENT_URL = env.VITE_PHONE_AGENT_URL || '';

/** Mock playback speed. "?speed=3" in the URL plays the demo 3x faster (handy for rehearsing). */
export const MOCK_SPEED = (() => {
  const v = Number(param('speed'));
  return v > 0 ? v : 1;
})();

