      const p = a.play();
      if (p && p.catch) p.catch(() => done(false));
    } catch {
      done(false);
    }
  });
}

function buildVetResult(story, lang, context) {
  const c = story.costs || {};
  return {
    kind: 'appointment',
    time: story.calendar?.appointment || '16:30',
    place: context.clinic?.name || (lang === 'zh' ? '诊所（演示）' : 'Clinic (demo)'),
    estimate: num(c.treatment, 600),
    currency: c.currency || 'CHF',
    note:
      lang === 'zh'
        ? '模拟：这是演示脚本，没有真的打电话，也没有真的预约。上门另加约 150 瑞郎。'
        : 'Simulated: demo script, no real call was made and nothing was booked. A home visit would add about CHF 150.',
    simulated: true,
  };
}

function buildInsuranceResult(story, lang) {
  const c = story.costs || {};
  const deductible = num(c.remaining_deductible, 300);
  const rate = num(c.reimbursement_rate, 0.8);
  const estimate = num(c.treatment, 600);
  const reimbursed = num(c.reimbursed, Math.max(estimate - deductible, 0) * rate);
  const cur = c.currency || 'CHF';
  const zh = lang === 'zh';
  const clinic = num(c.clinic, 385);
  const home = num(c.home, 510);
  return {
    kind: 'coverage',
    covered: true,
    currency: cur,
    deductible,
    rate,
    estimate,
    reimbursed,
    outOfPocket: estimate - reimbursed,
    points: [
      { ok: true, text: zh ? '意外从第一天起就保' : 'Accident covered from day 1' },
      {
        ok: true,
        text: zh
          ? `先付前 ${deductible} 瑞郎，之后报销 ${Math.round(rate * 100)}%`
          : `You pay the first ${cur} ${deductible}, then ${Math.round(rate * 100)}% is reimbursed`,
      },
      { ok: false, text: zh ? '上门费不保' : 'Home visit not covered', ref: 'AVB 1.2' },
      { ok: false, text: zh ? '之后的理疗不保' : 'Physiotherapy not covered', ref: 'AVB 1.2' },
      {
        ok: true,
        text: zh
          ? `估算自付：诊所约 ${cur} ${clinic}，上门约 ${cur} ${home}（含出租车 / 上门费）`
          : `Estimated cost to you: clinic about ${cur} ${clinic} vs home visit about ${cur} ${home}`,
      },
    ],
    simulated: true,
  };
}

export function createLivePhoneCall({ target = 'vet', lang = 'zh', context = {}, speed = 1 } = {}) {
  const base = PHONE_AGENT_URL || '';
  const listeners = new Set();
  const timers = new Set();
  const state = { ended: false, audio: null };
  let started = false;

  const emit = (e) => {
    if (!state.ended) listeners.forEach((l) => l(e));
  };
  const wait = (ms) =>
    new Promise((resolve) => {
      const id = setTimeout(() => {
        timers.delete(id);
        resolve();
      }, ms / speed);
      timers.add(id);
    });

  // Gradium audio only with explicit consent from the page (context.gradiumConsent === true);
  // the page may withdraw or give it mid-call with setGradiumConsent().
  const voice = context.voice === 'my_voice' ? 'my_voice' : 'standard';
  let gradiumConsent = context.gradiumConsent === true;
  const gradium = createGradiumLines(base, voice, state);
  const useGradium = () => gradiumConsent && !gradium.failed && !isSpeechMuted() && typeof fetch === 'function';

  // Tell the page which voice Pawse really uses; only emits when it changes (e.g. Gradium fails -> browser).
  let lastVoice = '';
  const announceVoice = (gradiumOk) => {
    const ev = phoneVoiceEvent({ gradiumOk, muted: isSpeechMuted(), variant: voice, browser: resolveVoiceName('de') });
    const sig = JSON.stringify(ev);
    if (sig !== lastVoice) {
      lastVoice = sig;
      emit(ev);
    }
  };

  async function say(lines, i) {
    const line = lines[i];
    if (line.who === 'ai' && !useGradium()) announceVoice(false);
    if (line.who === 'ai' && useGradium()) {
      const blob = await gradium.fetch(i, line.original);
      // Preload the next AI line while this one plays.
      const next = lines.findIndex((l, j) => j > i && l.who === 'ai');
      if (next >= 0 && useGradium()) gradium.fetch(next, lines[next].original);
      if (state.ended) return;
      announceVoice(!!blob);
      if (await playBlob(blob, state)) return;
      announceVoice(false); // Gradium failed or was not playable: the browser voice speaks this line
    }
    if (state.ended) return;
    await speak(line.original, 'de', { speed, pitch: line.who === 'callee' ? 0.8 : 1.15 });
  }

  async function run() {
    emit({ type: 'status', state: 'dialing' });
    let story;
    try {
      story = await fetchStory(base);
    } catch (err) {
      emit({ type: 'error', message: `Phone agent: ${err.message}` });
      finish();
      return;
    }
    await wait(1500);
    if (state.ended) return;
    emit({ type: 'status', state: 'connected' });
    announceVoice(useGradium());

    const step = (story.steps || [])[STEP_INDEX[target] ?? 2] || { lines: [] };
    const lines = [
      { who: 'ai', original: FIRST_LINE.original, text: FIRST_LINE.text[lang] ?? FIRST_LINE.text.en },
      ...(step.lines || []).map((l) => ({
        who: /^pawse/i.test(l.speaker) ? 'ai' : 'callee',
        original: l.german,
        // The backend subtitles are English; the zh UI shows them as is rather than inventing a translation.
        text: l.subtitle,
      })),
    ];
    for (const [i, line] of lines.entries()) {
      await wait(450);
      if (state.ended) return;
      emit({ type: 'speaking', who: line.who });
      const ev = { type: 'line', who: line.who, original: line.original, text: line.text };
      if (line.who === 'callee') ev.simulated = true;
      emit(ev);
      await say(lines, i);
      if (state.ended) return;
      emit({ type: 'speaking', who: 'none' });
    }
    await wait(500);
    if (state.ended) return;
    emit({ type: 'result', ...(target === 'insurance' ? buildInsuranceResult(story, lang) : buildVetResult(story, lang, context)) });
    finish();
  }

  function finish() {
    if (state.ended) return;
    emit({ type: 'status', state: 'ended' });
    state.ended = true;
    timers.forEach(clearTimeout);
    timers.clear();
    if (state.audio) {
      try { state.audio.pause(); } catch { /* ignore */ }
      state.audio = null;
    }
    stopSpeech();
  }

  return {
    on(cb) {
      listeners.add(cb);
      return () => listeners.delete(cb);
    },
    start() {
      if (started) return;
      started = true;
      run().catch((err) => {
        emit({ type: 'error', message: String(err && err.message ? err.message : err) });
        finish();
      });
    },
    hangup: finish,
    /** Give or withdraw consent for Gradium audio for the remaining lines of this call. */
    setGradiumConsent(on) {
      gradiumConsent = on === true;
    },
  };
}
// Scripted phone call: Pawse calls the vet or the insurer in German, in the background.
// The owner gets English progress steps, questions when a decision is needed, and the result;
// the German audio only plays if they choose to listen in.
// Implements the PHONE AGENT contract in ../contracts.js.

import { phoneScripts, buildVetResult, buildInsuranceResult, DEFAULT_ESTIMATE, AUTO_REPLY_MS } from './mockScripts.js';
import { speak, stopSpeech } from './speech.js';

export function createMockPhoneCall({ target = 'vet', lang = 'zh', context = {}, speed = 1 } = {}) {
  const script = phoneScripts[target] || phoneScripts.vet;
  const L = (o) => o[lang] ?? o.en;
  const listeners = new Set();
  const timers = new Set();
  const answers = {};
  let pendingQuestion = null; // { id, resolve }
  let listening = false;
  let started = false;
  let ended = false;

  const emit = (e) => {
    if (!ended) listeners.forEach((l) => l(e));
  };
  const wait = (ms) =>
    new Promise((resolve) => {
      const id = setTimeout(() => {
        timers.delete(id);
        resolve();
      }, ms / speed);
      timers.add(id);
    });

  // Pauses the call until the owner answers. In rehearsal / tests (speed > 1) the fallback is
  // picked automatically so the demo runs hands-free; at normal speed it waits for the owner.
  function ask(q) {
    emit({
      type: 'question',
      id: q.id,
      text: L(q.text),
      options: q.options.map((o) => ({ id: o.id, label: L(o.label) })),
    });
    return new Promise((resolve) => {
      pendingQuestion = { id: q.id, resolve };
      if (speed > 1) {
        const tid = setTimeout(() => answer(q.id, q.fallback), AUTO_REPLY_MS / speed);
        timers.add(tid);
      }
    });
  }

  function answer(id, optionId) {
    if (!pendingQuestion || pendingQuestion.id !== id) return;
    const { resolve } = pendingQuestion;
    pendingQuestion = null;
    answers[id] = optionId;
    emit({ type: 'answered', id, optionId });
    resolve(optionId);
  }

  async function playLines(lines) {
    for (const line of lines) {
      if (line.question) {
        const choice = await ask(line.question);
        if (ended) return;
        await playLines(line.branches[choice] || line.branches[line.question.fallback]);
        if (ended) return;
        continue;
      }
      await wait(450);
      if (ended) return;
      if (line.step) emit({ type: 'progress', text: L(line.step) });
      emit({ type: 'speaking', who: line.who });
      const ev = { type: 'line', who: line.who, original: line.de, text: L(line.text) };
      if (line.who === 'callee') ev.simulated = true; // scripted reply, nobody was called
      emit(ev);
      await speak(line.de, 'de', { speed, silent: !listening, pitch: line.who === 'callee' ? 0.8 : 1.15 });
      if (ended) return;
      emit({ type: 'speaking', who: 'none' });
    }
  }

  async function run() {
    emit({ type: 'status', state: 'dialing' });
    await wait(2400);
    if (ended) return;
    emit({ type: 'status', state: 'connected' });
    await playLines(script.lines);
    if (ended) return;
    await wait(500);
    if (ended) return;
    const result =
      target === 'insurance'
        ? buildInsuranceResult(
            lang,
            typeof context.estimate === 'number' ? context.estimate : DEFAULT_ESTIMATE,
            typeof context.homeVisitFee === 'number' ? context.homeVisitFee : 0
          )
        : buildVetResult(lang, context.clinic, answers.slot);
    emit({ type: 'result', ...result, simulated: true });
    emit({ type: 'status', state: 'ended' });
  }

  return {
    on(cb) {
      listeners.add(cb);
      return () => listeners.delete(cb);
    },
    start() {
      if (started) return;
      started = true;
      run();
    },
    answer,
    /** Play the German call audio (true) or keep it in the background (false, the default). */
    setListening(on) {
      listening = !!on;
      if (!listening) stopSpeech();
    },
    hangup() {
      if (ended) return;
      emit({ type: 'status', state: 'ended' });
      ended = true;
      pendingQuestion = null;
      timers.forEach(clearTimeout);
      timers.clear();
      stopSpeech();
    },
  };
}
import { VOICE_AGENT, CLINIC_SEARCH, PHONE_AGENT, MOCK_SPEED } from '../config.js';
import { createMockVoiceAgent } from './mockVoiceAgent.js';
import { createGeminiLiveAgent } from './geminiLiveAgent.js';
import { createLiveVoiceAgent } from './liveVoiceAgent.js';
import { mockSearchClinics } from './mockClinicSearch.js';
import { liveSearchClinics } from './liveClinicSearch.js';
import { createMockPhoneCall } from './mockPhoneAgent.js';
import { createLivePhoneCall } from './livePhoneAgent.js';

export const IS_LIVE_VOICE = VOICE_AGENT === 'live';
export const IS_LIVE_CLINICS = CLINIC_SEARCH === 'live';
export const IS_LIVE_PHONE = PHONE_AGENT === 'live';
export const IS_MOCK = !IS_LIVE_VOICE || !IS_LIVE_CLINICS || !IS_LIVE_PHONE;
// ?debug=1 shows raw agent traces (e.g. the voice call's "Agent results" box); off for owners.
export const DEBUG = new URLSearchParams(globalThis.location?.search || '').get('debug') === '1';

/** Which voice path runs: 'mock' (scripted), 'rest' (transcribe + care over REST) or 'native' (Gemini Live audio). */
export const VOICE_PATH = !IS_LIVE_VOICE ? 'mock' : new URLSearchParams(globalThis.location?.search || '').get('voice') === 'rest' ? 'rest' : 'native';

/** The page opens the microphone only if the active voice agent wants audio. */
export const VOICE_WANTS_AUDIO = IS_LIVE_VOICE;

/** 1. Voice conversation with Pawse. */
export function createVoiceAgent(opts) {
  return IS_LIVE_VOICE ? (new URLSearchParams(globalThis.location?.search || '').get('voice') === 'rest' ? createLiveVoiceAgent(opts) : createGeminiLiveAgent(opts)) : createMockVoiceAgent({ speed: MOCK_SPEED, ...opts });
}

/** 2. Nearby vet clinics. */
export function searchClinics(opts) {
  return IS_LIVE_CLINICS ? liveSearchClinics(opts) : mockSearchClinics({ speed: MOCK_SPEED, ...opts });
}

/** 3. Pawse calls the clinic or the insurer. */
export function createPhoneCall(opts) {
  return IS_LIVE_PHONE ? createLivePhoneCall(opts) : createMockPhoneCall({ speed: MOCK_SPEED, ...opts });
}

