export default function Plan({ t, lang, triage, vet, insurance, rail, onCall, onRestart }) {
  const [copied, setCopied] = useState(false);
  const summary = buildSummary({ lang, triage, vet, insurance });

  return (
    <main className="plan">
      {rail}
      <header className="plan-head">
        <Avatar size={56} />
