              <span className="cov-icon" aria-hidden="true">✓</span>
              <span>{c}</span>
            </li>
          ))}
        </ul>
      </section>

      <p className="disclaimer">{t.disclaimer}</p>
      <button type="button" className="btn ghost wide" onClick={onRestart}>
        {t.restart}
      </button>
