// Plain-text case summary (copy-paste ready), built from whatever has happened so far.

const LABELS = {
  zh: {
    plan: '安排',
    estimate: '预估费用',
    insurance: '保险',
    back: '预计报销',
    pay: '预计自付',
    notCovered: '不保',
    prepared: '已准备德语沟通稿，尚未拨打电话',
    vet: '兽医',
  },
  en: {
    plan: 'Plan',
    estimate: 'Estimate',
    insurance: 'Insurance',
    back: 'expected back',
    pay: 'you pay about',
    notCovered: 'not covered',
    prepared: 'German script prepared, no call placed',
    vet: 'Vet',
  },
};

export function buildSummary({ lang = 'zh', triage, vet, insurance }) {
  const L = LABELS[lang] || LABELS.en;
  const lines = [];
  if (triage && triage.summary) lines.push(triage.summary);
  if (vet && vet.prepared) lines.push(`${L.vet}: ${L.prepared}`);
  else if (vet) {
    lines.push(`${L.plan}: ${vet.time} · ${vet.place}`);
    lines.push(`${L.estimate}: ≈ ${vet.currency || 'CHF'} ${vet.estimate}`);
  }
  if (insurance && insurance.prepared) lines.push(`${L.insurance}: ${L.prepared}`);
  else if (insurance) {
    const cur = insurance.currency || 'CHF';
    lines.push(
      `${L.insurance}: ${L.back} ≈ ${cur} ${insurance.reimbursed} · ${L.pay} ≈ ${cur} ${insurance.outOfPocket}`
    );
    const no = (insurance.points || []).filter((p) => !p.ok);
    if (no.length) {
      lines.push(`${L.notCovered}: ${no.map((p) => (p.ref ? `${p.text} (${p.ref})` : p.text)).join('; ')}`);
    }
  }
  return lines.join('\n');
}
// Where the owner is in the story: talk → vet → insurance → summary. Derived from App state, never stored.
export const STEPS = ['talk', 'vet', 'insurance', 'summary'];

/** The plan's one obvious next action: the first unfinished conversation, then the summary. */
export function nextAction({ vet, insurance }) {
  if (!vet) return 'vet';
  if (!insurance) return 'insurance';
  return 'summary';
}

/** [{ id, done, current }] for the progress rail; exactly one step is current. */
export function stepState({ view, target, triage, vet, insurance }) {
  let current;
  if (view === 'voice' || !triage) current = 'talk';
  else if (view === 'clinics') current = 'vet';
  else if (view === 'phone') current = target === 'insurance' ? 'insurance' : 'vet';
  else current = nextAction({ vet, insurance });
  const done = { talk: !!triage && current !== 'talk', vet: !!vet, insurance: !!insurance, summary: false };
  return STEPS.map((id) => ({ id, done: done[id] && id !== current, current: id === current }));
}
// Where the owner is in the story: 1 Talk · 2 Vet · 3 Insurance · 4 Summary.
export default function StepRail({ t, steps }) {
  const at = steps.findIndex((s) => s.current);
  return (
    <nav className="step-rail" aria-label={t.stepOf(at + 1, steps.length)}>
      <ol>
        {steps.map((s, i) => (
          <li key={s.id} className={s.done ? 'done' : s.current ? 'current' : ''} aria-current={s.current ? 'step' : undefined}>
            <span className="step-dot" aria-hidden="true">{s.done ? '✓' : i + 1}</span>
            <span className="step-name">{t.rail[s.id]}</span>
          </li>
        ))}
      </ol>
    </nav>
  );
}

