.escalation {
  margin-top: 10px; font-size: 15px; font-weight: 600;
  background: #fde8ea; color: #8a1f2a; border-left: 4px solid var(--red);
  padding: 10px 12px; border-radius: 12px;
}

.actions { display: flex; flex-direction: column; gap: 10px; }
.action-row {
  display: flex; align-items: center; gap: 12px;
  background: var(--surface); border: 1.5px solid var(--line); border-radius: 18px; padding: 12px;
}
.action-row.done { border-color: #bfe3cf; background: #f2fbf6; }
.action-icon { width: 46px; height: 46px; flex: none; border-radius: 14px; display: grid; place-items: center; font-size: 24px; background: var(--soft); }
.action-text { flex: 1; min-width: 0; display: flex; flex-direction: column; line-height: 1.3; }
.action-text span { font-size: 14px; color: var(--muted); }
.action-row.done .action-text span { color: var(--green); font-weight: 700; }
.ai-note { margin-top: 8px; font-size: 13px; color: var(--muted); }

/* ---------------------------------------------------------- phone call */
.pc {
  max-width: 520px; margin: 0 auto; min-height: 100dvh; height: 100dvh;
  padding: calc(env(safe-area-inset-top) + 20px) var(--gutter) calc(env(safe-area-inset-bottom) + 16px);
  display: flex; flex-direction: column; gap: 12px; overflow-y: auto;
  background: linear-gradient(180deg, #ffe1ea 0%, var(--bg) 40%);
}
.pc-head { display: flex; flex-direction: column; align-items: center; gap: 4px; text-align: center; }
.pc-head h1 { font-size: 20px; font-weight: 900; margin-top: 4px; line-height: 1.2; }
.pc-callee {
