  display: flex; flex-direction: column; gap: 14px;
  background: radial-gradient(120% 40% at 50% 0%, #ffe1ea 0%, var(--bg) 70%);
}
.plan-head { display: flex; align-items: center; gap: 12px; }
.plan-head h1 { font-size: 24px; font-weight: 900; }
.card {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 14px 16px; display: flex; flex-direction: column; gap: 10px;
}
.card h2 { font-size: 17px; }
.card-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.summary {
  margin: 0; white-space: pre-wrap; word-break: break-word; font: inherit; font-size: 15px;
  background: var(--soft); border-radius: 14px; padding: 12px;
}

@media (prefers-reduced-motion: reduce) {
  .petal, .home-avatar, .pawse-avatar .eyes, .pawse-avatar.is-speaking .mouth, .rec-dot, .dots i,
  .pc-callee.ringing, .bridge-wire, .step, .step.now::before, .ask-card, .sheet, .line, .cap-ai, .cap-user, .kw-chip, .result-card, .halo, .clinic, .sk, .ctl.nudge, .cap-user.partial::after { animation: none; }
  .mic-ring, .level-bars i, .ctl.rec { transition: none; }
}

.sim-badge { display: inline-block; margin-left: 6px; padding: 1px 8px; border-radius: 999px; font-size: 11px; font-weight: 600; background: #fff3cd; color: #7a5b00; border: 1px solid #e6cf80; vertical-align: middle; }

/* Reviewed backend handoff shares existing app colours and spacing. */
.handoff label { display: block; margin: 12px 0; }
.handoff textarea, .handoff input[type="text"], .handoff input:not([type]), .handoff select { width: 100%; padding: 12px; border: 1px solid var(--line, #ddd); border-radius: 12px; font: inherit; box-sizing: border-box; }
.handoff textarea { min-height: 130px; resize: vertical; }
.handoff article { margin-top: 18px; overflow-wrap: anywhere; }
.handoff audio { width: 100%; margin-top: 12px; }

.voice-picker-icon i:nth-child(2) { animation-delay: 0.15s; } .voice-picker-icon i:nth-child(3) { animation-delay: 0.3s; }
.voice-picker-icon i:nth-child(4) { animation-delay: 0.45s; }
@keyframes vp-bounce { 50% { transform: scaleY(0.4); } }
@media (prefers-reduced-motion: reduce) { .voice-picker-icon i { animation: none !important; } }
.voice-picker.compact { margin: 6px auto 2px; }
.card .voice-picker { align-self: flex-start; margin-bottom: 4px; }

/* Step-by-step flow: progress rail (Talk · Vet · Insurance · Summary), collapsed sub-steps, tucked settings */
.step-rail ol { display: flex; gap: 6px; list-style: none; margin: 0 0 12px; padding: 0; }
.step-rail li { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 4px; font-size: 12px; color: var(--muted); }
.step-rail li::before { content: ''; align-self: stretch; height: 3px; border-radius: 2px; background: var(--line); }
.step-rail .step-dot { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; background: var(--soft); color: var(--muted); font-weight: 700; }
.step-rail li.done::before, .step-rail li.current::before { background: var(--brand); }
.step-rail li.done .step-dot { background: var(--brand); color: var(--brand-ink); }
.step-rail li.current { color: var(--ink); font-weight: 700; }
.step-rail li.current .step-dot { background: var(--surface); color: var(--brand-strong); box-shadow: 0 0 0 2px var(--brand); }
.substep-done { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 14px; border-radius: 14px; background: var(--soft); }
.card.focus { box-shadow: 0 0 0 2px var(--brand); }
.home-settings, .handoff-more { color: var(--muted); font-size: 14px; }
.home-settings summary, .handoff-more summary { cursor: pointer; min-height: 44px; display: flex; align-items: center; justify-content: center; padding: 0 12px; }
.home-settings[open], .handoff-more[open] { display: grid; gap: 8px; justify-items: center; }

