  const [confirm, setConfirm] = useState(null);
  const [taxi, setTaxi] = useState(null);
  const [story, setStory] = useState(mockStory);
  const [clinic, setClinic] = useState(null);"""),
("""  // Unknown status: still offer Gradium""","""  // The story numbers behind the calendar, option cards and checklist (live: /api/v1/demo/mimi).
  useEffect(() => {
    if (!IS_LIVE_PHONE) return undefined;
    let alive = true;
    loadStory({ live: true, base: PHONE_AGENT_URL || '' }).then((s) => alive && setStory(s));
    return () => {
      alive = false;
    };
  }, []);
  const facts = storyFacts(story);

  // Unknown status: still offer Gradium"""),
("  const Handoff = IS_LIVE_PHONE && !rehearsal ? LiveHandoff : PhoneCall;",
 """  // Live mode prepares the vet and insurer conversations for the owner (LiveHandoff) unless they chose
  // the rehearsal; the confirmation and taxi calls are always the scripted, simulated story calls.
  const scripted = target === 'confirm' || target === 'taxi';
  const Handoff = IS_LIVE_PHONE && !rehearsal && !scripted ? LiveHandoff : PhoneCall;"""),
("""    setInsurance(null);
    setClinic(null);
    setView('voice');""","""    setInsurance(null);
    setChoice(null);
    setConfirm(null);
    setTaxi(null);
    setClinic(null);
    setRehearsal(false);
    setView('voice');"""),
("""  const call = (to) => {
    setRehearsal(false);
    primeSpeech();
    if (to === 'vet') {
      setView('clinics');
      return;
    }
    setTarget(to);
    setView('phone');
  };

  const pickClinic = (c) => {
    setRehearsal(false);
    primeSpeech();""","""  // Rehearsal, once chosen, stays on for the rest of this story (vet → insurer → …) until "Call Pawse" again.
  const call = (to) => {
    primeSpeech();
    if (to === 'vet') {
      setView('clinics');
      return;
    }
    if (to === 'options') {
      setView('options');
      return;
    }
    if (to === 'summary') {
      setView('plan');
      return;
