input.command:
cd /home/azureuser/pawse-beats/web/src && cat >> styles.css <<'EOF'

/* Second half of the story: demo calendar, option cards (A clinic / B home visit), "Today" line. */
.pc-done { display: flex; flex-direction: column; gap: 8px; }

.cal-sheet {
  background: var(--surface); border: 1.5px solid var(--line); border-radius: 18px; padding: 12px 14px;
  display: flex; flex-direction: column; gap: 8px; animation: rise 0.3s ease;
}
.cal-head { display: flex; align-items: center; gap: 8px; }
.cal-head .sim-badge { margin-left: auto; }
.cal-icon { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; background: var(--soft); color: var(--brand-strong); font-weight: 900; }
.cal-slots { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; font-variant-numeric: tabular-nums; }
.cal-slots li { padding: 6px 10px; border-radius: 10px; font-size: 15px; border-left: 4px solid var(--line); }
.cal-busy { background: repeating-linear-gradient(135deg, var(--bg) 0 6px, var(--soft) 6px 12px); color: var(--muted); }
.cal-free { background: #f2fbf6; border-left-color: var(--green) !important; color: var(--green); font-weight: 700; }
.cal-pick { background: var(--soft); border-left-color: var(--brand) !important; color: var(--brand-strong); font-weight: 800; }

.options-head { display: flex; flex-direction: column; gap: 6px; }
.options-head h1 { font-size: 24px; font-weight: 900; line-height: 1.2; }
.options-head .sim-badge { margin-left: 0; }
.option-list { display: flex; flex-direction: column; gap: 12px; }
.option-card {
  appearance: none; text-align: left; display: flex; gap: 14px; align-items: flex-start; width: 100%;
  background: var(--surface); border: 2px solid var(--line); border-radius: var(--radius); padding: 14px 16px;
  transition: border-color 0.15s, box-shadow 0.15s; animation: rise 0.3s ease;
}
.option-card:hover { border-color: var(--petal); }
.option-card.picked { border-color: var(--brand); box-shadow: 0 0 0 3px rgba(200, 72, 122, 0.18); }
.option-letter {
  flex: none; width: 40px; height: 40px; border-radius: 12px; display: grid; place-items: center;
  font-size: 20px; font-weight: 900; background: var(--soft); color: var(--brand-strong);
}
.option-card.picked .option-letter { background: var(--brand); color: var(--brand-ink); }
.option-body { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.option-title { font-size: 18px; line-height: 1.25; }
.option-pay { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.option-amount { font-size: 28px; font-weight: 900; color: var(--brand-strong); font-variant-numeric: tabular-nums; line-height: 1.1; }
.option-detail { color: var(--muted); }
.options-hint { text-align: center; }

.today-line { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; font-variant-numeric: tabular-nums; }
.today-line li { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.today-line strong { font-size: 20px; font-weight: 900; }
.today-line li.ok strong { color: var(--ink); }
.today-line li.open strong { color: var(--muted); }
.today-arrow { color: var(--brand); font-weight: 900; font-size: 20px; }

@media (prefers-reduced-motion: reduce) { .cal-sheet, .option-card { animation: none; } }
EOF
grep -n "@keyframes rise" styles.css

